  let modes = [];
  let maxCount = 0;
  let count = 0;
  let prev = null;

  const inorder = (node) => {
    if (!node) return;
    inorder(node.left);
    if (node.val === prev) {
      count++;
    } else {
      count = 1;
    }
    prev = node.val;
    if (count > maxCount) {
      maxCount = count;
      modes = [node.val];
    } else if (count === maxCount) {
      modes.push(node.val);
    }
    inorder(node.right);
  };

  inorder(root);
  return modes;
}

