function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const small = size === 'small';
  const count = small ? 1 + pick(12) : 850 + pick(130);
  const ranges = small ? [1, 3, 6, 20, 100000] : [5, 40, 400, 100000];
  const span = ranges[pick(ranges.length)];
  const values = Array.from({ length: count }, () => pick(2 * span + 1) - span);
  // Sorted insertion order makes long chains.
  if (small && rand() < 0.2) values.sort((a, b) => (rand() < 0.5 ? a - b : b - a));
  let root = null;
  for (const value of values) {
    const node = { val: value, left: null, right: null };
    if (!root) { root = node; continue; }
    let at = root;
    for (;;) {
      // Equal keys may go to either side; both keep the tree valid.
      const side = value < at.val || (value === at.val && rand() < 0.5) ? 'left' : 'right';
      if (!at[side]) { at[side] = node; break; }
      at = at[side];
    }
  }
  const out = [];
  const queue = [root];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
